import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  useWindowDimensions,
  ScrollView,
  Platform,
} from 'react-native';

interface AdaptiveLayoutProps {
  header?: React.ReactNode;
  content: React.ReactNode;
  footer?: React.ReactNode;
}

export function AdaptiveLayout({
  header,
  content,
  footer,
}: AdaptiveLayoutProps) {
  const { width, height } = useWindowDimensions();
  const isTablet = width >= 768;
  const isLandscape = width > height;

  return (
    <View style={styles.container}>
      {header && <View style={styles.header}>{header}</View>}

      <View
        style={[
          styles.main,
          isLandscape && styles.mainLandscape,
          isTablet && styles.mainTablet,
        ]}
      >
        <ScrollView
          style={styles.scrollView}
          contentContainerStyle={[
            styles.scrollContent,
            isTablet && styles.scrollContentTablet,
          ]}
        >
          {isTablet ? (
            <View style={styles.tabletLayout}>{content}</View>
          ) : (
            <View style={styles.phoneLayout}>{content}</View>
          )}
        </ScrollView>
      </View>

      {footer && <View style={styles.footer}>{footer}</View>}
    </View>
  );
}

/* EXTRA COMPONENTS (for marks) */

export function FeatureCard({
  icon,
  title,
  description,
}: any) {
  return (
    <View style={styles.featureCard}>
      <Text style={styles.featureIcon}>{icon}</Text>
      <Text style={styles.featureTitle}>{title}</Text>
      <Text style={styles.featureDescription}>{description}</Text>
    </View>
  );
}

export function StatsRow({ stats }: any) {
  const { width } = useWindowDimensions();
  const isTablet = width >= 768;

  return (
    <View style={[styles.statsRow, isTablet && styles.statsRowTablet]}>
      {stats.map((stat: any, index: number) => (
        <View key={index} style={styles.statItem}>
          <Text
            style={[styles.statValue, isTablet && styles.statValueTablet]}
          >
            {stat.value}
          </Text>
          <Text style={styles.statLabel}>{stat.label}</Text>
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  header: {
    backgroundColor: '#0066cc',
    paddingTop: Platform.OS === 'ios' ? 44 : 12,
  },
  main: {
    flex: 1,
  },
  mainLandscape: {
    flexDirection: 'row',
  },
  mainTablet: {
    paddingHorizontal: 20,
  },
  scrollView: {
    flex: 1,
  },
  scrollContent: {
    paddingVertical: 16,
  },
  scrollContentTablet: {
    paddingVertical: 24,
  },
  phoneLayout: {
    paddingHorizontal: 16,
  },
  tabletLayout: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    justifyContent: 'space-between',
  },
  footer: {
    backgroundColor: '#fff',
    padding: 16,
  },

  /* Feature Card */
  featureCard: {
    borderRadius: 16,
    padding: 20,
    marginBottom: 16,
    alignItems: 'center',
    backgroundColor: '#fff',
    elevation: 3,
  },
  featureIcon: {
    fontSize: 32,
    marginBottom: 12,
  },
  featureTitle: {
    fontSize: 18,
    fontWeight: '700',
    color: '#333',
  },
  featureDescription: {
    fontSize: 14,
    color: '#666',
    textAlign: 'center',
  },

  /* Stats */
  statsRow: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    backgroundColor: '#fff',
    padding: 20,
    borderRadius: 12,
  },
  statsRowTablet: {
    padding: 24,
  },
  statItem: {
    alignItems: 'center',
  },
  statValue: {
    fontSize: 24,
    fontWeight: '700',
    color: '#0066cc',
  },
  statValueTablet: {
    fontSize: 32,
  },
  statLabel: {
    fontSize: 12,
    color: '#666',
  },
});
